draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw character
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // draw thinking bubble
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50 - 20 * Math.sin(t), 30, 0, 2 * Math.PI);
  ctx.stroke();

  // draw question marks
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('?', W/2, H/2 - 50 - 20 * Math.sin(t));

  // draw life path
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 50 * Math.cos(t), H - 20);
  ctx.stroke();

  ctx.restore();
}
